import React from "react";
import "../styles/Spinner.css";

type SpinnerProps = {
  size?: number;
};

function Spinner({ size=60 }: SpinnerProps) {
  return (
    <div
      className="spinner"
      style={{
        width: size ? "50%" : `60px`,
        height: size ? "50%" : `60px`,
      }}
    ></div>
  );
}

export default Spinner;
